package com.catpuzzle.assistant; import java.util.*; public final class PuzzleSolver{public enum Kind{CAT,CROSS,NONE}public static final class Move{public Kind kind;public int r,c;public String why;Move(Kind k,int r,int c,String w){kind=k;this.r=r;this.c=c;why=w;}}static class S{int n;int[][] reg;boolean[][] cat,block;ArrayList<int[]> sol=new ArrayList<>();}public static Move next(BoardAnalyzer.Board b){if(b==null)return new Move(Kind.NONE,-1,-1,"не вижу поле");if(b.confidence<.48f)return new Move(Kind.NONE,-1,-1,"неуверенно: "+b.note);S s=new S();s.n=b.n;s.reg=b.region;s.cat=b.cat;s.block=b.blocked;for(int r=0;r<s.n;r++)for(int c=0;c<s.n;c++)if(s.cat[r][c]){for(int cc=0;cc<s.n;cc++)if(cc!=c&&!s.block[r][cc]&&!s.cat[r][cc])return new Move(Kind.CROSS,r,cc,"в строке уже есть кот");for(int rr=0;rr<s.n;rr++)if(rr!=r&&!s.block[rr][c]&&!s.cat[rr][c])return new Move(Kind.CROSS,rr,c,"в столбце уже есть кот");for(int rr=Math.max(0,r-1);rr<=Math.min(s.n-1,r+1);rr++)for(int cc=Math.max(0,c-1);cc<=Math.min(s.n-1,c+1);cc++)if((rr!=r||cc!=c)&&!s.block[rr][cc]&&!s.cat[rr][cc])return new Move(Kind.CROSS,rr,cc,"коты не могут касаться");}go(s,0,new int[s.n],new boolean[s.n],new HashSet<Integer>());if(s.sol.isEmpty())return new Move(Kind.NONE,-1,-1,"решение не найдено");int z=s.sol.size();for(int r=0;r<s.n;r++)for(int c=0;c<s.n;c++)if(!s.cat[r][c]&&!s.block[r][c]){int k=0;for(int[] q:s.sol)if(q[r]==c)k++;if(k==z)return new Move(Kind.CAT,r,c,"кот во всех "+z+" решениях");}for(int r=0;r<s.n;r++)for(int c=0;c<s.n;c++)if(!s.cat[r][c]&&!s.block[r][c]){int k=0;for(int[] q:s.sol)if(q[r]==c)k++;if(k==0)return new Move(Kind.CROSS,r,c,"кот здесь невозможен");}return new Move(Kind.NONE,-1,-1,"нет однозначного хода");}static void go(S s,int r,int[] q,boolean[] col,HashSet<Integer> reg){if(s.sol.size()>=512)return;if(r==s.n){s.sol.add(q.clone());return;}int fixed=-1;for(int c=0;c<s.n;c++)if(s.cat[r][c]){if(fixed!=-1)return;fixed=c;}if(fixed>=0){cell(s,r,fixed,q,col,reg);return;}for(int c=0;c<s.n;c++)if(!s.block[r][c])cell(s,r,c,q,col,reg);}static void cell(S s,int r,int c,int[] q,boolean[] col,HashSet<Integer> reg){if(col[c])return;int g=s.reg[r][c];if(reg.contains(g))return;if(r>0&&Math.abs(q[r-1]-c)<=1)return;for(int rr=0;rr<s.n;rr++)for(int cc=0;cc<s.n;cc++)if(s.cat[rr][cc]&&(rr!=r||cc!=c)&&(rr==r||cc==c||s.reg[rr][cc]==g||Math.max(Math.abs(rr-r),Math.abs(cc-c))<=1))return;q[r]=c;col[c]=true;reg.add(g);go(s,r+1,q,col,reg);reg.remove(g);col[c]=false;}}